events.inlineCode:
// AdMob Interstitial Ad
if (typeof admob !== 'undefined' && admob.interstitial) {
    admob.interstitial.load({
        id: 'ca-app-pub-XXXXXXXXXXXXXXXX/XXXXXXXXXX'
    }).then(() => {
        admob.interstitial.show();
    }).catch(err => console.log('Ad Error:', err));
}

// AdMob Rewarded Ad
if (typeof admob !== 'undefined' && admob.rewardVideo) {
    admob.rewardVideo.load({
        id: 'ca-app-pub-XXXXXXXXXXXXXXXX/XXXXXXXXXX'
    }).then(() => {
        return admob.rewardVideo.show();
    }).then((result) => {
        if (result && result.type === 'rewarded') {
            runtimeScene.getGame().getVariables().get('TotalCoins').setNumber(
                runtimeScene.getGame().getVariables().get('TotalCoins').getAsNumber() + 50
            );
        }
    }).catch(err => console.log('Rewarded Ad Error:', err));
}
